import { expect, test, type Page } from "./helpers/monitorErrors";

const baseUrl = process.env.GALLERY_BASE_URL ?? "http://localhost:5173";
const rootPath = "/gallery-visual-layer-test";
const imagePaths = [
  `${rootPath}/a.png`,
  `${rootPath}/b.png`,
  `${rootPath}/c.png`,
];
const png1x1 = Buffer.from(
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAFgwJ/luz4nQAAAABJRU5ErkJggg==",
  "base64"
);

const jpgExifPortrait = Buffer.from(
  "",
  "base64"
);

type ApiRequest = { pathname: string; path: string };

function requestsFor(requests: ApiRequest[], pathname: string) {
  return requests.filter((request) => request.pathname === pathname);
}

async function installStubbedGallery(page: Page) {
  const requests: ApiRequest[] = [];

  await page.route("**/api/**", async (route) => {
    const url = new URL(route.request().url());
    const request: ApiRequest = {
      pathname: url.pathname,
      path: url.searchParams.get("path") ?? "",
    };
    requests.push(request);

    if (url.pathname === "/api/scan") {
      await route.fulfill({
        contentType: "application/json",
        headers: { "Cache-Control": "no-store" },
        body: JSON.stringify({
          folders: [],
          images: imagePaths.map((path, index) => ({
            name: `image-${index + 1}.png`,
            path,
            type: "image",
            mtime: 1000 + index,
            width: 1600,
            height: 1000,
          })),
          next_cursor: null,
          total_images: imagePaths.length,
        }),
      });
      return;
    }

    if (url.pathname === "/api/metadata") {
      await route.fulfill({
        contentType: "application/json",
        headers: { "Cache-Control": "no-store" },
        body: JSON.stringify({
          tool: "stub",
          prompt: "stub prompt",
          negative_prompt: "",
          params: {},
          date: "",
          generation_time: "",
          width: 1600,
          height: 1000,
          name: request.path.split("/").pop() ?? "image.png",
        }),
      });
      return;
    }

    if (url.pathname === "/api/landing-pages") {
      await route.fulfill({
        contentType: "application/json",
        headers: { "Cache-Control": "no-store" },
        body: JSON.stringify([]),
      });
      return;
    }

    if (["/api/thumbnail", "/api/preview", "/api/image"].includes(url.pathname)) {
      await route.fulfill({
        contentType: "image/png",
        headers: { "Cache-Control": "no-store" },
        body: png1x1,
      });
      return;
    }

    await route.fulfill({ status: 404, contentType: "application/json", body: "{}" });
  });

  return requests;
}

async function openStubbedGallery(page: Page) {
  await page.addInitScript((rootForInit) => {
    localStorage.setItem("intro_mode", "disabled");
    localStorage.setItem("gallery-root-path", rootForInit);
    localStorage.setItem("gallery-sort-preference", JSON.stringify({ field: "name", order: "asc" }));
    localStorage.removeItem("gallery-lightbox-always-load-original");
  }, rootPath);

  await page.goto(baseUrl, { waitUntil: "domcontentloaded" });
  await expect(page.getByTestId("photo-card").first()).toBeVisible({ timeout: 15_000 });
}

test.use({ viewport: { width: 1280, height: 820 } });

test("should have exactly one pswp root and no duplicate visible imgs", async ({ page }) => {
  const requests = await installStubbedGallery(page);
  await openStubbedGallery(page);

  await page.getByTestId("photo-card").first().click();
  await expect(page.getByTestId("lightbox")).toBeVisible({ timeout: 10_000 });
  await page.waitForTimeout(2000);

  const report = await page.evaluate(() => {
    const roots = document.querySelectorAll(".pswp");
    const allImgs = document.querySelectorAll<HTMLImageElement>(".pswp__img");
    const placeholders = document.querySelectorAll(".pswp__img--placeholder");

    const items = document.querySelectorAll<HTMLElement>(".pswp__item");
    const perItemCounts: { itemIdx: number; total: number; visible: number; visibleSrcs: string[] }[] = [];
    let totalVisibleImgs = 0;

    items.forEach((item, idx) => {
      const imgs = item.querySelectorAll<HTMLImageElement>(".pswp__img");
      let visible = 0;
      const visibleSrcs: string[] = [];
      imgs.forEach((img) => {
        const style = getComputedStyle(img);
        const rect = img.getBoundingClientRect();
        if (
          style.display !== "none" &&
          parseFloat(style.opacity) > 0 &&
          style.visibility !== "hidden" &&
          rect.width > 0 &&
          rect.height > 0
        ) {
          visible++;
          totalVisibleImgs++;
          visibleSrcs.push(img.src.slice(0, 120));
        }
      });
      perItemCounts.push({ itemIdx: idx, total: imgs.length, visible, visibleSrcs });
    });

    return {
      rootCount: roots.length,
      totalImgs: allImgs.length,
      totalVisibleImgs,
      placeholderCount: placeholders.length,
      perItemCounts,
    };
  });

  expect(report.rootCount).toBe(1);

  // Each .pswp__item must have at most 1 visible .pswp__img.
  // A count of 2+ signals the duplicate-img-tornado bug.
  for (const item of report.perItemCounts) {
    expect(
      item.visible,
      `.pswp__item[${item.itemIdx}] has ${item.visible} visible .pswp__img — duplicate bug?`
    ).toBeLessThanOrEqual(1);
  }

  // With preload: [1, 1], all 3 item holders may have loaded images.
  expect(report.totalVisibleImgs, "total visible imgs").toBeGreaterThanOrEqual(1);

  expect(requestsFor(requests, "/api/image")).toHaveLength(0);
});

test("should have exactly one pswp root after close and reopen", async ({ page }) => {
  const requests = await installStubbedGallery(page);
  await openStubbedGallery(page);

  // Open
  await page.getByTestId("photo-card").first().click();
  await expect(page.getByTestId("lightbox")).toBeVisible({ timeout: 10_000 });
  await page.waitForTimeout(1000);

  // Close
  await page.keyboard.press("Escape");
  await expect(page.getByTestId("lightbox")).not.toBeVisible({ timeout: 5000 });
  await page.waitForTimeout(500);

  // Reopen
  await page.getByTestId("photo-card").first().click();
  await expect(page.getByTestId("lightbox")).toBeVisible({ timeout: 10_000 });
  await page.waitForTimeout(2000);

  const rootCount = await page.evaluate(() => document.querySelectorAll(".pswp").length);
  expect(rootCount).toBe(1);
});

test.describe("EXIF-rotated portrait JPEG", () => {
  const exifRoot = "/gallery-exif-test";
  const exifImagePaths = [
    `${exifRoot}/iphone-photo.jpg`,
    `${exifRoot}/normal.png`,
  ];

  test.use({ viewport: { width: 390, height: 844 } });

  test("should render portrait aspect ratio for EXIF-rotated iPhone JPEG without duplicate imgs", async ({ page }) => {
    const requests: ApiRequest[] = [];

    await page.route("**/api/**", async (route) => {
      const url = new URL(route.request().url());
      const request: ApiRequest = {
        pathname: url.pathname,
        path: url.searchParams.get("path") ?? "",
      };
      requests.push(request);

      if (url.pathname === "/api/scan") {
        await route.fulfill({
          contentType: "application/json",
          headers: { "Cache-Control": "no-store" },
          body: JSON.stringify({
            folders: [],
            images: [
              {
                name: "iphone-photo.jpg",
                path: exifImagePaths[0],
                type: "image",
                mtime: 1000,
                width: 1080,
                height: 1440,
              },
              {
                name: "normal.png",
                path: exifImagePaths[1],
                type: "image",
                mtime: 1001,
                width: 1600,
                height: 1000,
              },
            ],
            next_cursor: null,
            total_images: exifImagePaths.length,
          }),
        });
        return;
      }

      if (url.pathname === "/api/metadata") {
        const isExif = request.path.includes("iphone-photo");
        await route.fulfill({
          contentType: "application/json",
          headers: { "Cache-Control": "no-store" },
          body: JSON.stringify({
            tool: "stub",
            prompt: "stub prompt",
            negative_prompt: "",
            params: {},
            date: "",
            generation_time: "",
            width: isExif ? 1080 : 1600,
            height: isExif ? 1440 : 1000,
            name: request.path.split("/").pop() ?? "image.jpg",
          }),
        });
        return;
      }

      if (url.pathname === "/api/landing-pages") {
        await route.fulfill({
          contentType: "application/json",
          headers: { "Cache-Control": "no-store" },
          body: JSON.stringify([]),
        });
        return;
      }

      if (url.pathname === "/api/thumbnail" || url.pathname === "/api/preview") {
        if (request.path.includes("iphone-photo")) {
          await route.fulfill({
            contentType: "image/jpeg",
            headers: { "Cache-Control": "no-store" },
            body: jpgExifPortrait,
          });
        } else {
          await route.fulfill({
            contentType: "image/png",
            headers: { "Cache-Control": "no-store" },
            body: png1x1,
          });
        }
        return;
      }

      if (url.pathname === "/api/image") {
        await route.fulfill({
          contentType: "image/jpeg",
          headers: { "Cache-Control": "no-store" },
          body: jpgExifPortrait,
        });
        return;
      }

      await route.fulfill({ status: 404, contentType: "application/json", body: "{}" });
    });

    await page.addInitScript((rootForInit) => {
      localStorage.setItem("intro_mode", "disabled");
      localStorage.setItem("gallery-root-path", rootForInit);
      localStorage.setItem("gallery-sort-preference", JSON.stringify({ field: "name", order: "asc" }));
      localStorage.removeItem("gallery-lightbox-always-load-original");
    }, exifRoot);

    await page.goto(baseUrl, { waitUntil: "domcontentloaded" });
    await expect(page.getByTestId("photo-card").first()).toBeVisible({ timeout: 15_000 });

    // Close mobile sidebar before interacting with photo cards
    await page.keyboard.press("Escape");
    await page.waitForTimeout(200);

    await page.getByTestId("photo-card").first().click();
    await expect(page.getByTestId("lightbox")).toBeVisible({ timeout: 10_000 });
    await page.waitForTimeout(3000);

    const report = await page.evaluate(() => {
      const roots = document.querySelectorAll(".pswp");
      const allImgs = document.querySelectorAll<HTMLImageElement>(".pswp__img");
      const placeholders = document.querySelectorAll(".pswp__img--placeholder");

      const items = document.querySelectorAll<HTMLElement>(".pswp__item");
      const perItemCounts: { itemIdx: number; total: number; visible: number; visibleSrcs: string[]; visibleRects: { w: number; h: number }[] }[] = [];
      let totalVisibleImgs = 0;
      let activePlaceholderRect: { w: number; h: number } | null = null;

      items.forEach((item, idx) => {
        const imgs = item.querySelectorAll<HTMLImageElement>(".pswp__img");
        let visible = 0;
        const visibleSrcs: string[] = [];
        const visibleRects: { w: number; h: number }[] = [];
        imgs.forEach((img) => {
          const style = getComputedStyle(img);
          const rect = img.getBoundingClientRect();
          if (
            style.display !== "none" &&
            parseFloat(style.opacity) > 0 &&
            style.visibility !== "hidden" &&
            rect.width > 0 &&
            rect.height > 0
          ) {
            visible++;
            totalVisibleImgs++;
            visibleSrcs.push(img.src.slice(0, 120));
            visibleRects.push({ w: rect.width, h: rect.height });
          }
        });
        perItemCounts.push({ itemIdx: idx, total: imgs.length, visible, visibleSrcs, visibleRects });
      });

      const activePlaceholders = document.querySelectorAll(".pswp__img--placeholder");
      activePlaceholders.forEach((ph) => {
        const phImg = ph as HTMLImageElement;
        const rect = phImg.getBoundingClientRect();
        const style = getComputedStyle(phImg);
        if (
          style.display !== "none" &&
          parseFloat(style.opacity) > 0 &&
          style.visibility !== "hidden"
        ) {
          activePlaceholderRect = { w: rect.width, h: rect.height };
        }
      });

      return {
        rootCount: roots.length,
        totalImgs: allImgs.length,
        totalVisibleImgs,
        placeholderCount: placeholders.length,
        perItemCounts,
        activePlaceholderRect,
      };
    });

    expect(report.rootCount).toBe(1);

    for (const item of report.perItemCounts) {
      expect(
        item.visible,
        `.pswp__item[${item.itemIdx}] has ${item.visible} visible .pswp__img — duplicate bug?`
      ).toBeLessThanOrEqual(1);
    }

    expect(report.totalVisibleImgs, "total visible imgs").toBeGreaterThanOrEqual(1);

    expect(requestsFor(requests, "/api/image")).toHaveLength(0);

    const activeItem = report.perItemCounts.find((item) => item.visible > 0);
    expect(activeItem, "active item with visible img should exist").toBeTruthy();
    if (activeItem && activeItem.visibleRects.length > 0) {
      const { w, h } = activeItem.visibleRects[0];
      expect(h, `preview rect height=${h} should be > width=${w} for portrait`).toBeGreaterThan(w);
      const aspectRatio = w / h;
      const expectedRatio = 1080 / 1440;
      expect(aspectRatio, `aspect ratio ${aspectRatio.toFixed(3)} ~= ${expectedRatio.toFixed(3)}`).toBeCloseTo(expectedRatio, 1);
    }
  });
});
